/*
 * Debug block at AMP_SHMEM_BASE (0x47c00000), readable from Linux devmem:
 *   +0x20 u32 rpmsg isr count (updated in rpmsg_platform.c)
 *   +0x24 u32 rx message count
 *   +0x28 u32 tx ok count
 *   +0x2c s32 last tx result
 *   +0x30 u32 last peer src addr
 *   +0x34 u32 link state (1 = up)
 */
#define DBG32(off)  (*(volatile uint32_t *)(0x47c00000UL + (off)))

static int32_t tty_ept_cb(void *payload, uint32_t payload_len, uint32_t src, void *priv)
{
    int32_t ret;

    g_peer = src;
    DBG32(0x24) = DBG32(0x24) + 1;
    DBG32(0x30) = src;

    rt_kprintf("[rpmsg] rx %d bytes from 0x%x: %.*s\n",
               (int)payload_len, (unsigned)src, (int)payload_len, (char *)payload);

    /* echo back to the sender */
    ret = rpmsg_lite_send(g_rl, g_ept, src, payload, payload_len, RL_DONT_BLOCK);
    DBG32(0x2c) = (uint32_t)ret;
    if (ret == RL_SUCCESS)
        DBG32(0x28) = DBG32(0x28) + 1;

    return RL_RELEASE;
}

