/****************************************************************************
 * board/contest_board/chip/rk3576_boot.c
 *
 * RK3576 (KickPi K7) AMP-slave chip boot: MMU map + board hook.
 *
 * AMP slave rules honoured here:
 *   - map ONLY what we own: the 8MB private carve-out, the shared-memory
 *     window (Normal Non-cacheable, matching the Linux side), and the
 *     peripheral window.  The rest of DRAM belongs to Linux and stays
 *     unmapped so a stray pointer faults instead of corrupting Linux.
 *   - no PSCI: this core is brought up by U-Boot via PSCI CPU_ON; calling
 *     PSCI from here (cpu on/off, system reset) would affect the whole SoC.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <arch/chip/chip.h>

#include "arm64_arch.h"
#include "arm64_internal.h"
#include "arm64_mmu.h"
#include "rk3576_boot.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct arm_mmu_region g_mmu_regions[] =
{
  MMU_REGION_FLAT_ENTRY("DEVICEIO",
                        CONFIG_DEVICEIO_BASEADDR, CONFIG_DEVICEIO_SIZE,
                        MT_DEVICE_NGNRNE | MT_RW | MT_SECURE),

  MMU_REGION_FLAT_ENTRY("DRAM_PRIVATE",
                        CONFIG_RAMBANK1_ADDR, CONFIG_RAMBANK1_SIZE,
                        MT_NORMAL | MT_RW | MT_SECURE),

  MMU_REGION_FLAT_ENTRY("AMP_SHM",
                        RK3576_AMP_SHM_BASE, RK3576_AMP_SHM_SIZE,
                        MT_NORMAL_NC | MT_RW | MT_SECURE),
};

const struct arm_mmu_config g_mmu_config =
{
  .num_regions = nitems(g_mmu_regions),
  .mmu_regions = g_mmu_regions,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void arm64_el_init(void)
{
  /* Entered from BL31 PSCI CPU_ON; no EL3/EL2 setup required here. */
}

void arm64_chip_boot(void)
{
  /* Map I/O, private DRAM and shared memory, then enable the MMU. */

  arm64_mmu_init(true);

  /* Board-level bring-up (UART5 clock/pinmux bootstrap etc.).  Must run
   * before the early serial init: nothing else on this SoC has programmed
   * UART5 for us at this point (we boot before Linux).
   */

  rk3576_board_initialize();

#ifdef USE_EARLYSERIALINIT
  arm64_earlyserialinit();
#endif
}

#if defined(CONFIG_NET) && !defined(CONFIG_NETDEV_LATEINIT)
void arm64_netinitialize(void)
{
  /* No networking on the AMP slave. */
}
#endif

/****************************************************************************
 * board/contest_board/chip/rk3576_serial.c
 *
 * UART5 console glue: the generic 16550 driver handles the DW APB UART
 * (REGWIDTH=32).  Clock and pinmux are programmed by
 * rk3576_board_initialize() before this runs.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_16550_UART

#include <nuttx/serial/uart_16550.h>

#include "arm64_internal.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void arm64_earlyserialinit(void)
{
  u16550_earlyserialinit();
}

void arm64_serialinit(void)
{
  u16550_serialinit();
}

#endif /* CONFIG_16550_UART */

/****************************************************************************
 * board/contest_board/src/board_boot.c
 *
 * KickPi K7 (RK3576) AMP slave board bring-up.
 *
 * This image boots BEFORE Linux, so it must program its own UART5 clock
 * gates and pin multiplexing (values match the kernel clk/pinctrl drivers;
 * Rockchip registers use a write-mask in the upper 16 bits).  Once Linux is
 * up, its rockchip-amp DTS node keeps these clocks/pins alive.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/board.h>

#include <arch/chip/chip.h>

#include "arm64_internal.h"
#include "rk3576_boot.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define RK3576_CLKSEL_CON(x)   (RK3576_CRU_BASE + 0x300 + (x) * 4)
#define RK3576_CLKGATE_CON(x)  (RK3576_CRU_BASE + 0x800 + (x) * 4)

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rk3576_board_initialize
 *
 * Description:
 *   Called from arm64_chip_boot() right after the MMU is enabled and
 *   before the early serial init.  Programs UART5 clocks and pinmux.
 *
 ****************************************************************************/

void rk3576_board_initialize(void)
{
  /* PCLK_UART5 ungate: CLKGATE_CON13 bit14 = 0 */

  putreg32((1u << 14) << 16, RK3576_CLKGATE_CON(13));

  /* SCLK_UART5 = xin24m / 1: CLKSEL_CON64 mux[10:8]=3, div[7:0]=0 */

  putreg32((((0x7u << 8) | 0xffu) << 16) | (3u << 8), RK3576_CLKSEL_CON(64));

  /* SCLK_UART5 ungate: CLKGATE_CON14 bit15 = 0 */

  putreg32((1u << 15) << 16, RK3576_CLKGATE_CON(14));

  /* iomux GPIO3_D4/D5 -> func9 (uart5_rx_m0 / uart5_tx_m0, 40-pin header) */

  putreg32(0x00ff0000 | (9u << 4) | 9u, RK3576_IOC_BASE + 0x407c);

  /* pull-up on RX (GPIO3_D4): PULL_GPIO3 + 0xc, bits[9:8] = 01 */

  putreg32(((0x3u << 8) << 16) | (0x1u << 8), RK3576_IOC_BASE + 0x613c);
}

/****************************************************************************
 * Name: board_late_initialize
 *
 * Description:
 *   Board late init: start the AMP heartbeat / defensive IRQ re-enable
 *   thread (see rk3576_heartbeat.c).
 *
 ****************************************************************************/

#ifdef CONFIG_BOARD_LATE_INITIALIZE
void board_late_initialize(void)
{
#ifdef CONFIG_RK3576_AMP_HEARTBEAT
  extern int rk3576_heartbeat_start(void);
  rk3576_heartbeat_start();
#endif
}
#endif

/****************************************************************************
 * board/contest_board/src/rk3576_heartbeat.c
 *
 * AMP heartbeat + defensive interrupt re-enable.
 *
 * Shared block at 0x47c00000 (read from Linux via devmem):
 *   +0x00 u32 magic   0x4b37414d ("K7AM")
 *   +0x04 u32 version 3 = openvela (1 = bare-metal, 2 = RT-Thread)
 *   +0x08 u64 counter (+1 every 500ms — proof of life & scheduling)
 *   +0x10 u64 cntpct  (generic timer timestamp of last beat)
 *   +0x18 u32 cntfrq
 *
 * The defensive re-enable exists because the Linux GIC init clears
 * GICD_ISENABLER bits once at boot (its vendor AMP patches preserve only
 * routing/priority for amp-irqs).  GICD_ISENABLER is write-1-to-set, so
 * re-asserting our own SPIs every 500ms is atomic and race-free.
 * Lesson learned (the hard way) on the RT-Thread port of this same board.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/kthread.h>
#include <nuttx/signal.h>

#include <stdint.h>

#include <arch/chip/chip.h>

#include "arm64_internal.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define HB_MAGIC        0x4b37414d
#define HB_VERSION      3           /* openvela */

#define HB32(off)       (*(volatile uint32_t *)(RK3576_HEARTBEAT_BASE + (off)))
#define HB64(off)       (*(volatile uint64_t *)(RK3576_HEARTBEAT_BASE + (off)))

#define GICD_ISENABLER(n) \
  (CONFIG_GICD_BASE + 0x100 + ((n) / 32) * 4)

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline uint64_t read_cntpct(void)
{
  uint64_t v;
  __asm__ volatile("isb; mrs %0, cntpct_el0" : "=r"(v));
  return v;
}

static inline uint64_t read_cntfrq(void)
{
  uint64_t v;
  __asm__ volatile("mrs %0, cntfrq_el0" : "=r"(v));
  return v;
}

static void hb_reenable_irq(int intid)
{
  putreg32(1u << (intid % 32), GICD_ISENABLER(intid));
}

static int rk3576_heartbeat_thread(int argc, char *argv[])
{
  uint64_t counter = 0;

  HB32(0x00) = HB_MAGIC;
  HB32(0x04) = HB_VERSION;
  HB32(0x18) = (uint32_t)read_cntfrq();

  for (; ; )
    {
      HB64(0x08) = ++counter;
      HB64(0x10) = read_cntpct();
      __asm__ volatile("dsb sy" ::: "memory");

      /* Defensive: our SPI enables must survive the Linux GIC init window */

      hb_reenable_irq(RK3576_IRQ_UART5);
      hb_reenable_irq(RK3576_IRQ_RPMSG_RX);

      nxsig_usleep(500 * 1000);
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int rk3576_heartbeat_start(void)
{
  return kthread_create("amp_hb", 100, 2048, rk3576_heartbeat_thread, NULL);
}

