/* Boot progress marker at 0x47c00040 (read from Linux via devmem), used to
 * locate where the slave crashes when no UART5 is attached.  Written with
 * the MMU both off (chip_boot entry) and on (after mmu_init).
 */

#define BOOT_STAGE(v)  (*(volatile uint32_t *)0x47c00040 = (v))

void arm64_chip_boot(void)
{
  BOOT_STAGE(0xB0000001);       /* reached chip_boot (MMU off) */

  /* Map I/O, private DRAM and shared memory, then enable the MMU. */

  arm64_mmu_init(true);

  BOOT_STAGE(0xB0000002);       /* MMU enabled */

  /* Board-level bring-up (UART5 clock/pinmux bootstrap etc.).  Must run
   * before the early serial init: nothing else on this SoC has programmed
   * UART5 for us at this point (we boot before Linux).
   */

  rk3576_board_initialize();

  BOOT_STAGE(0xB0000003);       /* board init done */

#ifdef USE_EARLYSERIALINIT
  arm64_earlyserialinit();
#endif

  BOOT_STAGE(0xB0000004);       /* early serial done, returning to nx_start */
}

