2	 * arch/arm64/src/rk3576/rk3576_soc.c
3	 *
4	 * RK3576 CRU (clock) and IOC (pinmux/pull) helpers for the AMP slave.
5	 *
6	 * Register layouts mirror the Linux drivers this core has to coexist with:
7	 *   clocks : drivers/clk/rockchip/clk-rk3576.c
8	 *   pins   : drivers/pinctrl/pinctrl-rockchip.c (rk3576_pin_banks and the
9	 *            rk3576_calc_pull_reg_and_bit() offsets)
10	 *
11	 * Every register here is a Rockchip "hiword mask" register — the upper 16
12	 * bits say which of the lower 16 bits the write applies to — so a write
13	 * touching only our bits cannot corrupt a field Linux owns.
14	 *
15	 * SPDX-License-Identifier: Apache-2.0
16	 ****************************************************************************/
17	
18	/****************************************************************************
19	 * Included Files
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	
24	#include <arch/chip/chip.h>
25	
26	#include "arm64_internal.h"
27	#include "rk3576_soc.h"
28	
29	/****************************************************************************
30	 * Pre-processor Definitions
31	 ****************************************************************************/
32	
33	/* IOMUX register offsets from RK3576_IOC_BASE, one per pin group (A/B/C/D).
34	 * Each 32-bit register covers 4 pins (4 bits each) in its low half, so a
35	 * group of 8 pins spans two consecutive registers.
36	 */
37	
38	static const uint32_t g_iomux_offset[5][4] =
39	{
40	  { 0x0000, 0x0008, 0x2004, 0x200c },   /* bank0 A B C D */
41	  { 0x4020, 0x4028, 0x4030, 0x4038 },   /* bank1         */
42	  { 0x4040, 0x4048, 0x4050, 0x4058 },   /* bank2         */
43	  { 0x4060, 0x4068, 0x4070, 0x4078 },   /* bank3         */
44	  { 0x4080, 0x4088, 0xa390, 0xb398 },   /* bank4         */
45	};
46	
47	/****************************************************************************
48	 * Private Functions
49	 ****************************************************************************/
50	
51	/****************************************************************************
52	 * Name: rk3576_pull_reg
53	 *
54	 * Description:
55	 *   Base offset of the pull register covering a pin, mirroring
56	 *   rk3576_calc_pull_reg_and_bit() in the Linux pinctrl driver.  Pull
57	 *   fields are 2 bits wide, 8 pins per register.
58	 *
59	 ****************************************************************************/
60	
61	static uint32_t rk3576_pull_reg(unsigned int bank, unsigned int pin)
62	{
63	  uint32_t reg;
64	
65	  switch (bank)
66	    {
67	    case 0:
68	      reg = (pin < 12) ? 0x0020 : (0x2028 - 0x4);
69	      break;
70	
71	    case 1:
72	      reg = 0x6110;
73	      break;
74	
75	    case 2:
76	      reg = 0x6120;
77	      break;
78	
79	    case 3:
80	      reg = 0x6130;
81	      break;
82	
83	    case 4:
84	    default:
85	      if (pin < 16)
86	        {
87	          reg = 0x6140;
88	        }
89	      else if (pin < 24)
90	        {
91	          reg = 0xa148 - 0x8;
92	        }
93	      else
94	        {
95	          reg = 0xb14c - 0xc;
96	        }
97	      break;
98	    }
99	
100	  return reg + (pin / 8) * 4;
101	}
102	
103	/****************************************************************************
104	 * Public Functions
105	 ****************************************************************************/
106	
107	void rk3576_clk_gate(unsigned int con, unsigned int bit, bool enable)
108	{
109	  /* Gate bits are active low: 0 lets the clock run. */
110	
111	  uint32_t val = enable ? 0u : (1u << bit);
112	
113	  putreg32(((1u << bit) << 16) | val, RK3576_CLKGATE_CON(con));
114	}
115	
116	void rk3576_clk_set_mux_div(unsigned int con,
117	                            unsigned int mux_shift, unsigned int mux_width,
118	                            unsigned int mux,
119	                            unsigned int div_shift, unsigned int div_width,
120	                            unsigned int div)
121	{
122	  uint32_t mask = 0;
123	  uint32_t val  = 0;
124	
125	  if (mux_width != 0)
126	    {
127	      uint32_t m = (1u << mux_width) - 1u;
128	
129	      mask |= m << mux_shift;
130	      val  |= (mux & m) << mux_shift;
131	    }
132	
133	  if (div_width != 0)
134	    {
135	      uint32_t m = (1u << div_width) - 1u;
136	
137	      /* Hardware stores (divider - 1) */
138	
139	      mask |= m << div_shift;
140	      val  |= ((div - 1u) & m) << div_shift;
141	    }
142	
143	  if (mask != 0)
144	    {
145	      putreg32((mask << 16) | val, RK3576_CLKSEL_CON(con));
146	    }
147	}
148	
149	void rk3576_iomux(unsigned int bank, unsigned int pin, unsigned int func)
150	{
151	  uint32_t reg;
152	  uint32_t shift;
153	
154	  if (bank > 4 || pin > 31)
155	    {
156	      return;
157	    }
158	
159	  /* Group selects the base offset, the upper nibble of the group selects
160	   * which of the two registers, and the position inside that register is
161	   * 4 bits per pin.
162	   */
163	
164	  reg   = g_iomux_offset[bank][pin / 8] + (((pin % 8) >= 4) ? 4 : 0);
165	  shift = (pin % 4) * 4;
166	
167	  putreg32((0xfu << (shift + 16)) | ((func & 0xfu) << shift),
168	           RK3576_IOC_BASE + reg);
169	}
170	
171	void rk3576_pull(unsigned int bank, unsigned int pin, unsigned int pull)
172	{
173	  uint32_t reg;
174	  uint32_t shift;
175	
176	  if (bank > 4 || pin > 31)
177	    {
178	      return;
179	    }
180	
181	  reg   = rk3576_pull_reg(bank, pin);
182	  shift = (pin % 8) * 2;
183	
184	  putreg32((0x3u << (shift + 16)) | ((pull & 0x3u) << shift),
185	           RK3576_IOC_BASE + reg);
186	}
