/****************************************************************************
 * arch/arm64/src/rk3576/rk3576_pdm.c
 *
 * RK3576 PDM capture for the openvela AMP slave.
 *
 * Register layout and the programming sequence follow the Linux driver this
 * core coexists with: sound/soc/rockchip/rockchip_pdm.{c,h} (RK3576 uses the
 * "rockchip,rk3588-pdm" variant).  As with the SAI we do not use DMA — the
 * three PL330 DMACs belong to Linux — so a polling thread drains the FIFO.
 *
 * Unlike an I2S MEMS mic, a PDM mic returns a raw 1-bit oversampled stream;
 * the decimation filter that turns it into PCM is inside the PDM block, so
 * there is nothing to do in software.
 *
 * Clocking.  Everything is derived from the 24 MHz crystal, never from the
 * audio PLLs: those belong to Linux and it retunes them whenever it plays
 * audio, which would drag our sample rate along.
 *
 *   mclk_pdm1 = xin24m / 1                        = 24 MHz  (filter clock)
 *   PDM clock = mclk_pdm1 * FD_NUM / FD_DEN       = 1.2 MHz (pin, to the mic)
 *   sample rate = PDM clock / decimation          = 18750 Hz
 *
 * The FD ratio of 20 is exactly the one Rockchip's own clkref table uses
 * (40.96 MHz / 2.048 MHz), which is why 1.2 MHz rather than a rounder number:
 * staying on a proven mclk/pin-clock ratio matters more than a nominal rate,
 * and 1.2 MHz is inside every PDM MEMS mic's normal-mode clock range.  The
 * resulting 18750 Hz is reported to the host, so playback stays in tune.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>

#include <errno.h>
#include <stdint.h>

#include <arch/chip/chip.h>

#include "arm64_internal.h"
#include "rk3576_pdm.h"
#include "rk3576_soc.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Register offsets (sound/soc/rockchip/rockchip_pdm.h) */

#define PDM_SYSCONFIG           0x0000
#define PDM_CTRL0               0x0004
#define PDM_CTRL1               0x0008
#define PDM_CLK_CTRL            0x000c
#define PDM_HPF_CTRL            0x0010
#define PDM_FIFO_CTRL           0x0014
#define PDM_DMA_CTRL            0x0018
#define PDM_INT_EN              0x001c
#define PDM_INT_CLR             0x0020
#define PDM_INT_ST              0x0024
#define PDM_RXFIFO_DATA         0x0030
#define PDM_DATA_VALID          0x0054
#define PDM_VERSION             0x0058

/* SYSCONFIG */

#define PDM_RX_START            (1u << 2)
#define PDM_RX_STOP             (0u << 2)
#define PDM_RX_CLR_WR           (1u << 0)

/* CTRL0 */

#define PDM_MODE_LJ             (1u << 31)  /* left justified in the word  */
#define PDM_PATH0_EN            (1u << 27)
#define PDM_SAMPLERATE(x)       ((x) << 5)
#define PDM_VDW(x)              (((x) - 1) << 0)

/* CTRL1: fractional divider producing the pin clock from mclk_pdm1 */

#define PDM_FD_NUMERATOR(x)     ((x) << 16)
#define PDM_FD_DENOMINATOR(x)   ((x) << 0)

/* CLK_CTRL */

#define PDM_PATH(x, v)          ((v) << (8 + (x) * 2))
#define PDM_CLK_FD_RATIO_40     (0u << 6)
#define PDM_CLK_FD_RATIO_35     (1u << 6)
#define PDM_CLK_EN              (1u << 5)
#define PDM_CKP_NORMAL          (0u << 3)
#define PDM_CIC_RATIO(x)        ((x) << 0)

/* HPF_CTRL: a DC-blocking high-pass, mandatory for PDM mics */

#define PDM_HPF_LE              (1u << 3)
#define PDM_HPF_RE              (1u << 2)
#define PDM_HPF_60HZ            (1u << 0)

/* FIFO_CTRL holds the current fill level in its low byte */

#define PDM_FIFO_CNT(x)         ((x) & 0xff)

/* Clock plan, see the file header.
 *
 * mclk_pdm1 is CLKSEL_CON51 mux[7:5] / div[4:0], gate CLKGATE_CON9 bit 8.
 * audio_frac_int_p mux 0 = xin24m (drivers/clk/rockchip/clk-rk3576.c).
 */

#define PDM_XIN_HZ              24000000
#define PDM_MCLK_DIV            1
#define PDM_MCLK_HZ             (PDM_XIN_HZ / PDM_MCLK_DIV)

#define PDM_FD_NUM              1
#define PDM_FD_DEN              20
#define PDM_PIN_CLK_HZ          (PDM_MCLK_HZ * PDM_FD_NUM / PDM_FD_DEN)

/* SAMPLERATE selects the decimation: Rockchip's table pairs a 2.048 MHz pin
 * clock with 8 kHz at code 0, and each code up halves the decimation.  Code 2
 * is therefore /64.
 */

#define PDM_SR_CODE             2
#define PDM_DECIMATION          64
#define PDM_CIC_RATIO_VAL       1

#define PDM_SAMPLE_RATE         (PDM_PIN_CLK_HZ / PDM_DECIMATION)

/* CRU bits for PDM1 (drivers/clk/rockchip/clk-rk3576.c)
 *   MCLK_PDM1     CLKSEL_CON51 mux[7:5] div[4:0]   gate CON9 bit8
 *   CLK_PDM1      CLKSEL_CON50 mux[11:9] div[8:0]  gate CON9 bit5
 *   HCLK_PDM1                                      gate CON9 bit7
 *   CLK_PDM1_OUT  (child of clk_pdm1)              gate CON3 bit5
 */

#define PDM_MCLK_CLKSEL_CON     51
#define PDM_MCLK_MUX_SHIFT      5
#define PDM_MCLK_MUX_WIDTH      3
#define PDM_MCLK_MUX_XIN24M     0
#define PDM_MCLK_DIV_SHIFT      0
#define PDM_MCLK_DIV_WIDTH      5

#define PDM_CLK_CLKSEL_CON      50
#define PDM_CLK_MUX_SHIFT       9
#define PDM_CLK_MUX_WIDTH       3
#define PDM_CLK_DIV_SHIFT       0
#define PDM_CLK_DIV_WIDTH       9

#define PDM_GATE_CON            9
#define PDM_GATE_CLK_BIT        5
#define PDM_GATE_HCLK_BIT       7
#define PDM_GATE_MCLK_BIT       8
#define PDM_OUT_GATE_CON        3
#define PDM_OUT_GATE_BIT        5

/* pdm1m1 pins, all function 3 on bank 4 */

#define PDM_PIN_CLK0            RK3576_PIN_A(6)
#define PDM_PIN_CLK1            RK3576_PIN_B(0)
#define PDM_PIN_SDI1            RK3576_PIN_B(2)
#define PDM_PIN_FUNC            3

/* SDI1 feeds internal path 0 */

#define PDM_SDI_INDEX           1

/* Delays the Linux driver applies (PDM_START_DELAY_MS_DEFAULT and
 * PDM_FILTER_DELAY_MS_MIN): the mic needs to wake once the clock appears,
 * and the decimation filter produces garbage until it settles.
 */

#define PDM_START_DELAY_MS      20
#define PDM_FILTER_DELAY_MS     20

/* Treat the FIFO as in trouble at this level.  The depth is not documented;
 * PDM_DMA_RDL is 7 bits so it is at least 64.  If the real depth is smaller
 * this never trips and rk3576_pdm_maxfifo() reports the truth instead.
 */

#define PDM_FIFO_HIGH           96

/****************************************************************************
 * Private Data
 ****************************************************************************/

static uint32_t g_pdm_overruns;
static uint32_t g_pdm_maxfifo;
static uint32_t g_pdm_slot;             /* next FIFO word's channel, 0 or 1 */
static int      g_pdm_channel;          /* channel handed out as mono       */
static uint16_t g_pdm_peak[2];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline uint32_t pdm_getreg(unsigned int off)
{
  return getreg32(RK3576_PDM1_BASE + off);
}

static inline void pdm_putreg(unsigned int off, uint32_t val)
{
  putreg32(val, RK3576_PDM1_BASE + off);
}

/****************************************************************************
 * Name: rk3576_pdm_clk_init
 *
 * Description:
 *   Point PDM1 at the 24 MHz crystal and ungate everything the block needs.
 *
 ****************************************************************************/

static void rk3576_pdm_clk_init(void)
{
  /* Filter clock: xin24m / PDM_MCLK_DIV */

  rk3576_clk_set_mux_div(PDM_MCLK_CLKSEL_CON,
                         PDM_MCLK_MUX_SHIFT, PDM_MCLK_MUX_WIDTH,
                         PDM_MCLK_MUX_XIN24M,
                         PDM_MCLK_DIV_SHIFT, PDM_MCLK_DIV_WIDTH,
                         PDM_MCLK_DIV);

  /* clk_pdm1 / clk_pdm1_out.  The Linux driver only enables these and never
   * sets a rate — the pin clock comes out of the block's own fractional
   * divider — but program them to the same 1.2 MHz anyway, so the output is
   * correct whichever of the two actually reaches the pad.
   */

  rk3576_clk_set_mux_div(PDM_CLK_CLKSEL_CON,
                         PDM_CLK_MUX_SHIFT, PDM_CLK_MUX_WIDTH,
                         PDM_MCLK_MUX_XIN24M,
                         PDM_CLK_DIV_SHIFT, PDM_CLK_DIV_WIDTH,
                         PDM_XIN_HZ / PDM_PIN_CLK_HZ);

  rk3576_clk_gate(PDM_GATE_CON, PDM_GATE_MCLK_BIT, true);
  rk3576_clk_gate(PDM_GATE_CON, PDM_GATE_HCLK_BIT, true);
  rk3576_clk_gate(PDM_GATE_CON, PDM_GATE_CLK_BIT, true);
  rk3576_clk_gate(PDM_OUT_GATE_CON, PDM_OUT_GATE_BIT, true);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int rk3576_pdm_capture_init(void)
{
  rk3576_pdm_clk_init();

  /* pdm1m1: both clock outputs plus the sdi1 data line */

  rk3576_iomux(RK3576_GPIO_BANK4, PDM_PIN_CLK0, PDM_PIN_FUNC);
  rk3576_iomux(RK3576_GPIO_BANK4, PDM_PIN_CLK1, PDM_PIN_FUNC);
  rk3576_iomux(RK3576_GPIO_BANK4, PDM_PIN_SDI1, PDM_PIN_FUNC);
  rk3576_pull(RK3576_GPIO_BANK4, PDM_PIN_SDI1, RK3576_PULL_NONE);

  /* Halt the receiver and flush while we program */

  pdm_putreg(PDM_SYSCONFIG, PDM_RX_STOP | PDM_RX_CLR_WR);

  /* One stereo path, 32-bit words, left justified.  32 bits keeps one sample
   * per FIFO word, which makes draining unambiguous (same choice as the SAI
   * driver); the useful magnitude sits in the top 16 bits.
   */

  pdm_putreg(PDM_CTRL0, PDM_MODE_LJ | PDM_PATH0_EN |
                        PDM_SAMPLERATE(PDM_SR_CODE) | PDM_VDW(32));

  /* Pin clock = mclk * num / den */

  pdm_putreg(PDM_CTRL1, PDM_FD_NUMERATOR(PDM_FD_NUM) |
                        PDM_FD_DENOMINATOR(PDM_FD_DEN));

  /* Route sdi1 to path 0, declare the mclk/pin-clock ratio bracket (20 is in
   * the "<= 35" one), and set the CIC decimation bracket for a ~1-3 MHz pin
   * clock.  Leave the clock itself off until start().
   */

  pdm_putreg(PDM_CLK_CTRL, PDM_PATH(0, PDM_SDI_INDEX) |
                           PDM_CLK_FD_RATIO_35 | PDM_CKP_NORMAL |
                           PDM_CIC_RATIO(PDM_CIC_RATIO_VAL));

  pdm_putreg(PDM_HPF_CTRL, PDM_HPF_LE | PDM_HPF_RE | PDM_HPF_60HZ);

  /* No DMA, no interrupts: this core polls */

  pdm_putreg(PDM_DMA_CTRL, 0);
  pdm_putreg(PDM_INT_EN, 0);

  g_pdm_overruns = 0;
  g_pdm_maxfifo  = 0;
  g_pdm_slot     = 0;
  g_pdm_channel  = 0;
  g_pdm_peak[0]  = 0;
  g_pdm_peak[1]  = 0;

  return PDM_SAMPLE_RATE;
}

void rk3576_pdm_start(void)
{
  uint32_t clkctrl = pdm_getreg(PDM_CLK_CTRL);

  /* Clock first: the microphone only starts converting once it sees one, and
   * it needs a moment to wake up.
   */

  pdm_putreg(PDM_CLK_CTRL, clkctrl | PDM_CLK_EN);
  up_mdelay(PDM_START_DELAY_MS);

  /* Then the receiver, and give the decimation filter time to settle before
   * we keep anything it produces.
   */

  pdm_putreg(PDM_SYSCONFIG, PDM_RX_START);
  up_mdelay(PDM_FILTER_DELAY_MS);

  /* Drop the settling garbage and realign to channel 0 */

  pdm_putreg(PDM_SYSCONFIG, PDM_RX_START | PDM_RX_CLR_WR);
  g_pdm_slot = 0;
}

void rk3576_pdm_stop(void)
{
  uint32_t clkctrl = pdm_getreg(PDM_CLK_CTRL);

  pdm_putreg(PDM_SYSCONFIG, PDM_RX_STOP | PDM_RX_CLR_WR);
  pdm_putreg(PDM_CLK_CTRL, clkctrl & ~PDM_CLK_EN);
}

size_t rk3576_pdm_read(int16_t *buf, size_t nsamples)
{
  size_t   got   = 0;
  uint32_t level = PDM_FIFO_CNT(pdm_getreg(PDM_FIFO_CTRL));

  if (level > g_pdm_maxfifo)
    {
      g_pdm_maxfifo = level;
    }

  if (level >= PDM_FIFO_HIGH)
    {
      g_pdm_overruns++;
    }

  while (got < nsamples && level != 0)
    {
      uint32_t raw = pdm_getreg(PDM_RXFIFO_DATA);
      int16_t  s   = (int16_t)(raw >> 16);
      uint16_t mag = (uint16_t)(s < 0 ? -(int32_t)s : s);

      if (mag > g_pdm_peak[g_pdm_slot])
        {
          g_pdm_peak[g_pdm_slot] = mag;
        }

      /* The two channels alternate in the FIFO; hand out only ours. */

      if ((int)g_pdm_slot == g_pdm_channel)
        {
          buf[got++] = s;
        }

      g_pdm_slot ^= 1;
      level--;
    }

  return got;
}

void rk3576_pdm_set_channel(int ch)
{
  g_pdm_channel = (ch != 0) ? 1 : 0;
}

void rk3576_pdm_peaks(uint16_t *ch0, uint16_t *ch1)
{
  *ch0 = g_pdm_peak[0];
  *ch1 = g_pdm_peak[1];

  g_pdm_peak[0] = 0;
  g_pdm_peak[1] = 0;
}

uint32_t rk3576_pdm_overruns(void)
{
  return g_pdm_overruns;
}

uint32_t rk3576_pdm_maxfifo(void)
{
  return g_pdm_maxfifo;
}

/****************************************************************************
 * board/contest_board/src/rk3576_mic.c
 *
 * AMP microphone demo: openvela owns a digital microphone on the 40-pin
 * header and streams the captured PCM to Linux over the rpmsg channel, where
 * it can be played back through the Linux-owned ES8388 codec/speaker.
 *
 *   microphone --PDM/I2S--> cpu3 (openvela) --rpmsg--> Linux /dev/ttyRPMSG0
 *
 * Two front ends are supported, picked at build time:
 *   CONFIG_RK3576_PDM  PDM1, for a PDM MEMS mic   (CLK GPIO4_A6/GPIO4_B0,
 *                                                  DATA GPIO4_B2)
 *   CONFIG_RK3576_SAI  SAI2, for an I2S MEMS mic  (SCLK/LRCK/SDI on
 *                                                  GPIO1_D1/D2/D3)
 * PDM wins if both are enabled.
 *
 * The same endpoint carries a tiny text protocol so the host can drive it:
 *
 *   echo MIC_START > /dev/ttyRPMSG0    start streaming raw PCM
 *   echo MIC_STOP  > /dev/ttyRPMSG0    stop streaming
 *   echo MIC_INFO  > /dev/ttyRPMSG0    reply with rate/format/health
 *   echo MIC_CH0   > /dev/ttyRPMSG0    take the other channel of the data
 *   echo MIC_CH1   > /dev/ttyRPMSG0      line (PDM only, see MIC_INFO peaks)
 *   anything else                      echoed back (link check)
 *
 * Recording from Linux is then just:
 *   stty -F /dev/ttyRPMSG0 raw -echo
 *   echo MIC_START > /dev/ttyRPMSG0; timeout 5 cat /dev/ttyRPMSG0 > mic.raw
 *   aplay -f S16_LE -r <hz> -c 1 mic.raw
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <nuttx/kthread.h>
#include <nuttx/rpmsg/rpmsg.h>

#ifdef CONFIG_RK3576_PDM
#  include "rk3576_pdm.h"
#else
#  include "rk3576_sai.h"
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Front-end shim.  Both drivers expose the same shape, so the threads below
 * do not care which microphone is wired up.
 */

#ifdef CONFIG_RK3576_PDM
#  define mic_hw_init()      rk3576_pdm_capture_init()
#  define mic_hw_start()     rk3576_pdm_start()
#  define mic_hw_stop()      rk3576_pdm_stop()
#  define mic_hw_read(b, n)  rk3576_pdm_read(b, n)
#  define mic_hw_overruns()  rk3576_pdm_overruns()
#  define MIC_SAMPLE_BITS    RK3576_PDM_SAMPLE_BITS
#  define MIC_CHANNELS       RK3576_PDM_CHANNELS
#  define MIC_FRONTEND       "pdm"
#else
#  define mic_hw_init()      rk3576_sai_capture_init()
#  define mic_hw_start()     rk3576_sai_start()
#  define mic_hw_stop()      rk3576_sai_stop()
#  define mic_hw_read(b, n)  rk3576_sai_read(b, n)
#  define mic_hw_overruns()  rk3576_sai_overruns()
#  define MIC_SAMPLE_BITS    RK3576_SAI_SAMPLE_BITS
#  define MIC_CHANNELS       RK3576_SAI_CHANNELS
#  define MIC_FRONTEND       "i2s"
#endif

/* An rpmsg buffer is 512 bytes on this link (fixed by the Rockchip master),
 * so keep each PCM chunk comfortably below the usable payload.
 */

#define MIC_CHUNK_SAMPLES   224         /* 448 bytes of 16-bit PCM */

/* The capture FIFO holds only a couple of milliseconds, far less than a
 * single rpmsg_sendto() can take.  So the capture thread does nothing but
 * drain the FIFO into this ring, and a second thread ships it out; without
 * that split the FIFO overruns on every send.  1/2 second of slack.
 */

#define MIC_RING_SAMPLES    8192

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct rpmsg_endpoint g_mic_ept;
static bool                  g_mic_bound;
static volatile bool         g_mic_want;      /* host asked us to stream */
static volatile bool         g_mic_running;   /* hardware is actually on */
static volatile uint32_t     g_mic_peer;
static int                   g_mic_rate;

static int16_t               g_mic_ring[MIC_RING_SAMPLES];
static volatile uint32_t     g_mic_head;   /* written by the capture thread */
static volatile uint32_t     g_mic_tail;   /* written by the sender thread  */
static volatile uint32_t     g_mic_dropped;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rk3576_mic_ept_cb
 *
 * Description:
 *   Host -> slave commands.  Anything unrecognised is echoed back, which
 *   keeps the original link-check demo working.
 *
 *   Starting and stopping the hardware is left to the capture thread: the
 *   PDM start sequence has to wait out the microphone's wake-up and the
 *   decimation filter's settling time, which has no business happening in an
 *   rpmsg callback.
 *
 ****************************************************************************/

static int rk3576_mic_ept_cb(FAR struct rpmsg_endpoint *ept, FAR void *data,
                             size_t len, uint32_t src, FAR void *priv)
{
  FAR const char *cmd = data;
  char info[128];

  g_mic_peer = src;

  if (len >= 9 && strncmp(cmd, "MIC_START", 9) == 0)
    {
      g_mic_want = true;
    }
  else if (len >= 8 && strncmp(cmd, "MIC_STOP", 8) == 0)
    {
      g_mic_want = false;
    }
  else if (len >= 7 && strncmp(cmd, "MIC_CH", 6) == 0 &&
           (cmd[6] == '0' || cmd[6] == '1'))
    {
#ifdef CONFIG_RK3576_PDM
      rk3576_pdm_set_channel(cmd[6] - '0');
#endif
    }
  else if (len >= 8 && strncmp(cmd, "MIC_INFO", 8) == 0)
    {
      int n;

#ifdef CONFIG_RK3576_PDM
      uint16_t p0;
      uint16_t p1;

      rk3576_pdm_peaks(&p0, &p1);
      n = snprintf(info, sizeof(info),
                   "MIC src=%s rate=%d bits=%d ch=%d ovr=%lu drop=%lu "
                   "peak0=%u peak1=%u fifomax=%lu\n",
                   MIC_FRONTEND, g_mic_rate, MIC_SAMPLE_BITS, MIC_CHANNELS,
                   (unsigned long)mic_hw_overruns(),
                   (unsigned long)g_mic_dropped,
                   (unsigned)p0, (unsigned)p1,
                   (unsigned long)rk3576_pdm_maxfifo());
#else
      n = snprintf(info, sizeof(info),
                   "MIC src=%s rate=%d bits=%d ch=%d ovr=%lu drop=%lu\n",
                   MIC_FRONTEND, g_mic_rate, MIC_SAMPLE_BITS, MIC_CHANNELS,
                   (unsigned long)mic_hw_overruns(),
                   (unsigned long)g_mic_dropped);
#endif
      rpmsg_sendto(ept, info, n, src);
    }
  else
    {
      /* Plain echo, as before */

      rpmsg_sendto(ept, data, (int)len, src);
    }

  return 0;
}

/****************************************************************************
 * Name: rk3576_mic_capture_thread
 *
 * Description:
 *   Own the capture hardware: apply start/stop requests and drain the RX
 *   FIFO into the ring.  Neither front end has a usable FIFO-level
 *   interrupt, so this polls; that is affordable because this core runs
 *   nothing else, and it keeps the audio path free of the PL330 DMACs
 *   (which all belong to Linux).
 *
 ****************************************************************************/

static int rk3576_mic_capture_thread(int argc, FAR char *argv[])
{
  int16_t burst[64];

  for (; ; )
    {
      size_t got;
      size_t i;

      if (g_mic_want != g_mic_running)
        {
          if (g_mic_want)
            {
              g_mic_head = g_mic_tail = 0;
              mic_hw_start();
            }
          else
            {
              mic_hw_stop();
            }

          g_mic_running = g_mic_want;
        }

      if (!g_mic_running)
        {
          usleep(20 * 1000);
          continue;
        }

      got = mic_hw_read(burst, sizeof(burst) / sizeof(burst[0]));
      if (got == 0)
        {
          /* Nothing yet; come back well before the FIFO could fill up. */

          usleep(500);
          continue;
        }

      for (i = 0; i < got; i++)
        {
          uint32_t next = (g_mic_head + 1) % MIC_RING_SAMPLES;

          if (next == g_mic_tail)
            {
              g_mic_dropped++;    /* host is not draining fast enough */
              break;
            }

          g_mic_ring[g_mic_head] = burst[i];
          g_mic_head = next;
        }
    }

  return 0;
}

static int rk3576_mic_send_thread(int argc, FAR char *argv[])
{
  static int16_t chunk[MIC_CHUNK_SAMPLES];

  for (; ; )
    {
      size_t n = 0;

      if (!g_mic_running || !g_mic_bound)
        {
          usleep(20 * 1000);
          continue;
        }

      while (n < MIC_CHUNK_SAMPLES && g_mic_tail != g_mic_head)
        {
          chunk[n++] = g_mic_ring[g_mic_tail];
          g_mic_tail = (g_mic_tail + 1) % MIC_RING_SAMPLES;
        }

      if (n == 0)
        {
          usleep(2 * 1000);
          continue;
        }

      rpmsg_sendto(&g_mic_ept, chunk, n * sizeof(int16_t), g_mic_peer);
    }

  return 0;
}

/****************************************************************************
 * Name: rk3576_mic_device_created / destroy
 ****************************************************************************/

static void rk3576_mic_device_created(FAR struct rpmsg_device *rdev,
                                      FAR void *priv)
{
  if (strcmp("linux", rpmsg_get_cpuname(rdev)) == 0)
    {
      rpmsg_create_ept(&g_mic_ept, rdev, "rpmsg-tty",
                       RPMSG_ADDR_ANY, RPMSG_ADDR_ANY,
                       rk3576_mic_ept_cb, NULL);
      g_mic_bound = true;
    }
}

static void rk3576_mic_device_destroy(FAR struct rpmsg_device *rdev,
                                      FAR void *priv)
{
  if (strcmp("linux", rpmsg_get_cpuname(rdev)) == 0)
    {
      g_mic_bound = false;
      g_mic_want  = false;
      rpmsg_destroy_ept(&g_mic_ept);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rk3576_mic_init
 *
 * Description:
 *   Bring up the capture front end and register the rpmsg endpoint that
 *   carries the PCM to Linux.  Replaces rk3576_rpmsg_echo_init() when a
 *   microphone front end is configured (the echo behaviour is preserved).
 *
 ****************************************************************************/

int rk3576_mic_init(void)
{
  int ret;

  ret = mic_hw_init();
  if (ret < 0)
    {
      return ret;
    }

  g_mic_rate = ret;

  /* Capture must outrank the sender: the FIFO has no slack. */

  kthread_create("amp_mic_cap", 200, 2048, rk3576_mic_capture_thread, NULL);
  kthread_create("amp_mic_tx", 120, 2048, rk3576_mic_send_thread, NULL);

  return rpmsg_register_callback(NULL,
                                 rk3576_mic_device_created,
                                 rk3576_mic_device_destroy,
                                 NULL, NULL);
}

