/* Keep cpu3-owned peripheral clocks alive against Linux clk gating:
 * UART5 = openvela console, SAI2 = openvela I2S microphone.
 */
clocks = <&cru SCLK_UART5>, <&cru PCLK_UART5>,
	 <&cru MCLK_SAI2_2CH_SRC>, <&cru MCLK_SAI2_2CH>,
	 <&cru HCLK_SAI2_2CH>;

/* SAI2 lives in PD_AUDIO.  Linux would gate that domain off as
 * soon as its own audio is idle, taking the slave's microphone
 * with it, so hold the domain up here (rockchip_amp.c does a
 * pm_runtime_resume_and_get() on it).
 */
power-domains = <&power RK3576_PD_AUDIO>;

/* Claim the 40-pin header pins the slave owns:
 *   UART5 console  GPIO3_D4/D5      (pins 23/21)
 *   SAI2 I2S mic   GPIO1_D1/D2/D3   (pins 18/26/28)
 */
pinctrl-names = "default";
pinctrl-0 = <&uart5m0_xfer>,
	    <&sai2m0_sclk>, <&sai2m0_lrck>, <&sai2m0_sdi>;

/* SAI2 itself stays disabled on the Linux side: the AMP slave programs the
 * controller directly.  Linux keeps SAI1/ES8388 (speaker + on-board mic).
 */
&sai2 {
	status = "disabled";
};

