static int get_pdm_v2_clkref(struct rk_pdm_v2_dev *pdm, unsigned int sr)
{
	int i, clk_ref = 0;

	if (!sr)
		return -EINVAL;

	for (i = 0; i < ARRAY_SIZE(clkref); i++) {
		if (sr % clkref[i].sr)
			continue;

		if (clkref[i].clk_out % sr)
			continue;

		if (pdm->clk_ref_frq != 0) {
			if (pdm->clk_ref_frq != clkref[i].clk)
				continue;
		}

		clk_ref = 1;
		break;
	}

	if (clk_ref)
		return i;
	else
		return -EINVAL;
}

